    "/wizard/deal/{dealId}/required-info": {
        /**
         * Step 1 continuation — citizen submits answers to the required_info
         * questions the OWL reasoner produced at define time. Validates every
         * declared key is answered, persists answers on `problem.answers`,
         * and advances the state machine analyzing → codified via the
         * orchestrator. Per DEAL_RUNTIME/06_WIZARD_INTEGRATION.md §32-64
         */
        post: operations["deals.wizard.required_info"];
    };
    "/wizard/deal/{dealId}/codify": {
        /**
         * Step 2 — solution generation. Calls OpenAI (HTTP-fakeable in
         * tests) to produce 3 solutions, stakeholders[], and a financing
         * envelope. Persists everything on the Deal. Does NOT advance the
         * state machine — the deal is already in `codified` after the
         * required-info call. Per DEAL_RUNTIME/06_WIZARD_INTEGRATION.md §66-148
         */
        post: operations["deals.wizard.codify"];
    };
    "/wizard/deal/{dealId}/codify-suggestions": {
        /**
         * WS5 (#285) / #144 remainder — GET /api/wizard/deal/{deal_id}/codify-suggestions
         * @description Read-only view of the ALREADY-PERSISTED Step-2 artifacts: the deal's
         * solutions (deal_instances.solutions), its versioned
         * deal_solution_proposals, the classifier-suggested codeset key, and the
         * linked draft policy + typed parameter proposals the codify bridge
         * wrote. Never generates anything — codify() is the write path.
         */
        get: operations["deals.wizard.codify_suggestions"];
    };
    "/wizard/deal/{dealId}/select-solution": {
        /**
         * Step 2 user action — pick one of the 3 generated solutions.
         * Sets selected_solution_idx; does NOT advance state. Per
         * DEAL_RUNTIME/06_WIZARD_INTEGRATION.md §81-84
         */
        post: operations["deals.wizard.select_solution"];
    };
    "/wizard/deal/{dealId}/setup": {
        /**
         * Step 3 — materialize pipeline_steps + DealStepAssignment rows,
         * advance state codified → setup. Per
         * DEAL_RUNTIME/06_WIZARD_INTEGRATION.md §168-212
         */
        post: operations["deals.wizard.setup"];
    };
    "/wizard/deal/{dealId}/start": {
        /**
         * Step 3 → 4 transition — citizen confirms ready to execute. State
         * machine setup → executing. Per
         * DEAL_RUNTIME/06_WIZARD_INTEGRATION.md §185
         */
        post: operations["deals.wizard.start"];
    };
    "/wizard/deal/{dealId}/metadata": {
        /**
         * Step 1 of the intake wizard — title, description, applicant type,
         * and optional related industries. Mirrors into `problem.title`,
         * `problem.description`, `problem.related_industries`. Sets
         * `applicant_type` as a first-class column
         */
        patch: operations["deals.wizard.metadata"];
    };
    "/wizard/deal/{dealId}/details": {
        /**
         * Step 2 of the intake wizard — customer reference, program window,
         * and budget tier. Budget tier drives the downstream Compute deposit
         * ladder (see ComputeController::topupIntent)
         */
        patch: operations["deals.wizard.details"];
    };
    "/wizard/deal/{dealId}/files": {
        /**
         * Step 3 of the intake wizard — multipart file upload. Stores the
         * file on the application's default disk (s3 in production, faked
         * to in-memory in tests via Pest's beforeEach hook) and writes a
         * `deal_files` row
         * @description `file_type` is constrained at the application layer to
         * {'document','image','logo'}; the schema column is free-form to
         * accept future kinds without a migration.
         */
        post: operations["deals.wizard.files"];
    };
    "/wizard/deal/{dealId}/files/{fileId}": {
        /**
         * Mid-wizard file removal. When the user un-attaches a file from
         * the Dropzone preview on step 4 (or removes the logo on step 2),
         * sys/ calls this so the DealFile row and the on-disk object don't
         * orphan. Idempotent — returns 404 if the file doesn't exist, 204
         * on a successful delete or a no-op
         */
        delete: operations["deals.wizard.files.destroy"];
    };
    "/wizard/deal/{dealId}/path": {
        /**
         * Step 4 of the intake wizard — selected path tier. Drives the
         * visual / SLA tier on the deal card and the downstream pipeline
         * template
         */
        patch: operations["deals.wizard.path"];
    };
    "/wizard/deal/{dealId}/submit": {
        /**
         * Step 5 of the intake wizard — submit. Validates that all four
         * prior intake steps recorded their data, then advances the deal
         * analyzing → `awaiting_compute` through the orchestrator's state
         * machine (#1412 0.1 — previously a raw off-enum write). Downstream
         * `agt/` handlers pick the deal up from that state once a Compute
         * deposit lands via Stripe webhook (see ComputeController::topupIntent
         * + ProgramSaleController::handleWebhook → DealOrchestrator::launchDeal)
         * @description Resubmitting an already-parked deal is an idempotent 200 no-op
         * (sys/ retries on flaky networks); submitting from any state past
         * the park (codified/setup/…) is an explicit 422 invalid_state —
         * the pre-#1412 silent state overwrite is gone.
         */
        post: operations["deals.wizard.submit"];
    };
    "/wizard/deal/{dealId}/compute-deposit": {
        /**
         * Compute deposit — mint a Stripe PaymentIntent funding the 5-tier
         * deposit (pink $1, green $10, blue $100, red $1,000, black $10,000)
         * for this deal and persist a `pending` DealComputeDeposit row keyed
         * by the PI id. The webhook handler (ProgramSaleController →
         * ProgramPurchase::handleProgramPurchase) flips it to `succeeded` and
         * dispatches DealLaunchJob on payment_intent.succeeded
         * @description Authorization mirrors the existing wizard step gates: the deal must
         * resolve under the request's tenant scope (the SubprojectScoped
         * trait on Deal already enforces this on Deal::find), and the same
         * `auth:api` middleware that protects /setup, /start, /submit gates
         * this route too.
         */
        post: operations["deals.wizard.compute_deposit"];
    };
    "/public/deal/launch-intent": {
        /**
         * OpenYC front door — anonymous "intent → launch" in ONE call. Mints a
         * temporary owner (so the deal has a creator membership and the launch has
         * a user context), builds the deal via the SAME path as define()
         * (classification + slot resolution + public-channel activation), and mints
         * the F3 compute-deposit PaymentIntent. The visitor confirms the returned
         * client_secret with Stripe; payment_intent.succeeded → the global webhook
         * → DealLaunchJob → the agt orchestrator starts the program
         * @description Unauthenticated by design (OpenYC visitors hold no token). The tenant is
         * resolved server-side from X-Domain; the temp user is scoped to it. An
         * already-authenticated caller keeps their own identity (no temp user).
         */
        post: operations["deals.public.launch_intent"];
    };
