    "/h5i/deals/{guid}/public-comment": {
        /**
         * Anonymous public-deal ENGAGEMENT — post a comment onto a published
         * deal's conversation (CROSS-REPO PINNED CONTRACT T3.c)
         * @description POST /api/h5i/deals/{guid}/public-comment   body: { body: string }
         *
         * Gate: identical to index() — an `active` PublicDealChannel row scoped
         * to the resolved tenant (see resolveSubprojectId). The comment is streamed
         * through the SAME H5iMessageBroker path the agent step lines use, so it
         * persists to h5i_messages (appears in the next public-messages poll under
         * `messages[]`) and broadcasts to the public channel. Returns the frontend
         * PublicDealComment shape { id, body, created_at, author }.
         */
        post: operations["h5i.deals.public-comment"];
    };
    "/h5i/deals/{guid}/hitl/{slug}/respond": {
        /**
         * Anonymous public-deal ENGAGEMENT — RESOLVE a pending human-in-the-loop
         * gate on a published deal (CROSS-REPO PINNED CONTRACT T3.c)
         * @description POST /api/h5i/deals/{guid}/hitl/{slug}/respond
         *   body: { decision: 'approve'|'input', input?: string }
         *   ({slug} == the sentinel 'deal' resolves the deal-level, slug-less gate.)
         *
         * Gate: identical to index(). Records a `deal.step.hitl` resolved
         * deal_event (so the next public-messages poll drops the gate from
         * `hitl[]`) and forwards the decision to agt on the `agent.requests` queue
         * as a `hitl_decision` task so the runtime can continue the blocked step.
         * The agt-side consumption of that decision is owned by the agt charter;
         * the api side is fully implemented + tested here.
         *
         * Returns the frontend HitlRespondResult shape { slug, state }.
         */
        post: operations["h5i.deals.hitl-respond"];
    };
