            /**
             * @description m2m tokens are cross-tenant by convention, so the target tenant
             * comes explicitly in the payload (validated against the token's
             * per-tenant policy:draft:<tld> ability in the controller).
             */
            subproject_id: number;
            title: string;
            summary?: string | null;
            body?: string | null;
            rationale?: string | null;
