    "auth.guestRegister": {
        requestBody: {
            content: {
                "application/json": components["schemas"]["MobGuestRegisterRequest"];
            };
        };
        responses: {
            200: {
                content: {
                    "application/json": string;
                };
            };
            422: components["responses"]["ValidationException"];
        };
    };
    /**
     * Guest → registered upgrade (CI-API#98). The authenticated guest
     * supplies real credentials; the SAME user row flips to a registered
     * account so the device's activity history survives the upgrade
     * @description "Is a guest" is decided from the markers guest-register creates:
     * the mob-source `external_user_links` row proves the account was
     * minted for a MOB device, and `is_temporary` (still true) proves it
     * has not been upgraded yet — this method zeroes it, the same flag
     * User::completeRegistration zeroes for the core signup flow. No new
     * column, no reliance on the incidental `@guest.local` email pattern.
     *
     * Token rotation: EVERY prior bearer for the user is revoked (the
     * calling one included — guest-register mints a fresh bearer per call,
     * so several may be live) and one new token is minted with the same
     * `subproject:{id}` ability stamping generateAuthDataForUser applies
     * (both funnel through subprojectTokenAbilities).
     *
     * Conflict semantics follow the Deals controllers: a caller that is
     * not an un-upgraded MOB guest gets 409 CONFLICT. Email collisions are
     * a 422 from MobUpgradeRequest's `unique:users,email` rule.
     */
    "auth.upgrade": {
        requestBody: {
            content: {
                "application/json": components["schemas"]["MobUpgradeRequest"];
            };
        };
        responses: {
            200: {
                content: {
                    "application/json": {
                        data: {
                            user: {
                                id: number;
                                name: string;
                                email: string;
                                roles: string;
                                subproject_id: number | null;
                                created_at: string;
                            };
                            token: {
                                access_token: string;
                                /** @enum {string} */
                                token_type: "Bearer";
                            };
                        };
                    };
                };
            };
            401: components["responses"]["AuthenticationException"];
            409: {
                content: {
                    "application/json": {
                        /** @enum {string} */
                        message: "Account already upgraded.";
                    } | {
                        /** @enum {string} */
                        message: "Not a MOB guest account.";
                    };
                };
            };
            422: components["responses"]["ValidationException"];
        };
    };
