    /**
     * GET /api/compute/meter — free-meter status for the current identity
     * @description An entitled user (or a topup-entitled guest) is never metered:
     * {entitled:true, remaining_units:null}. Everyone else resolves to a
     * verified guest key (MINT-ON-MISS, mirroring /status) and sees their
     * remaining free units + the in-flight metered session kind.
     */
    "compute.meterStatus": {
        responses: {
            200: {
                content: {
                    "application/json": Record<string, never> | {
                        data: {
                            entitled: boolean;
                            remaining_units: null;
                        };
                    };
                };
            };
        };
    };
    /**
     * POST /api/compute/meter/start {kind: listen|process} — open a metered
     * session. Entitled identities (user wallet OR confirmed guest top-up)
     * get {entitled:true, remaining_units:null} and are NOT metered; an
     * exhausted, unpurchased guest gets 402 {error:'compute_required'}
     */
    "compute.meterStart": {
        requestBody: {
            content: {
                "application/json": {
                    /** @enum {string} */
                    kind: "listen" | "process";
                };
            };
        };
        responses: {
            200: {
                content: {
                    "application/json": Record<string, never> | {
                        data: {
                            entitled: boolean;
                            remaining_units: null;
                        };
                    };
                };
            };
            422: components["responses"]["ValidationException"];
        };
    };
    /**
     * POST /api/compute/meter/beat — heartbeat for the active metered
     * session. The SERVER computes the charge (elapsed seconds since the
     * last beat, capped at compute.meter_max_beat_gap). 402 when the free
     * allowance hits zero (and no top-up bails the guest out)
     */
    "compute.meterBeat": {
        responses: {
            200: {
                content: {
                    "application/json": Record<string, never> | {
                        data: {
                            entitled: boolean;
                            remaining_units: null;
                        };
                    };
                };
            };
        };
    };
    /**
     * POST /api/compute/meter/stop — close the active metered session
     * (one final capped charge). Always 200 with the units remaining
     */
    "compute.meterStop": {
        responses: {
            200: {
                content: {
                    "application/json": Record<string, never> | {
                        data: {
                            entitled: boolean;
                            remaining_units: null;
                        };
                    };
                };
            };
        };
    };
