    /**
     * Server-driven scoring: Laravel synchronously calls CI-MCE
     * @description The wizard does NOT hit this over HTTP — DealWizardController
     * calls CiMceScoreService in-process after the define/start
     * transitions (flag `deals.cimce_score_on_transition`), avoiding
     * IdempotencyMiddleware + re-auth + the central-domain tenancy
     * wall. This endpoint remains for external Sanctum callers that
     * want to force a re-score.
     *
     * Behavior change vs the pre-service inline create: an OK-but-empty
     * upstream body no longer persists a row of nulls — the service
     * requires a composite_score or non-empty components, and this
     * endpoint returns 502 for a hollow response. (The endpoint had
     * zero callers when this changed; see ENDPOINT-VERDICTS.md.)
     */
    "dealScore.run": {
        parameters: {
            path: {
                dealId: string;
            };
        };
        requestBody?: {
            content: {
                "application/json": {
                    deal?: string;
                };
            };
        };
        responses: {
            201: {
                content: {
                    "application/json": {
                        /** @enum {string} */
                        schema_version: "1";
                        data: components["schemas"]["DealEconomicScore"] | null;
                    };
                };
            };
            401: components["responses"]["AuthenticationException"];
            502: {
                content: {
                    "application/json": {
                        /** @enum {string} */
                        schema_version: "1";
                        errors: [
                            {
                                /** @enum {integer} */
                                code: 502;
                                /** @enum {string} */
                                message: "ci-mce upstream failure or empty payload";
                            }
                        ];
                    };
                };
            };
        };
    };
    "deals.public.status": {
        parameters: {
            path: {
                guid: string;
            };
        };
        responses: {
            /**
             * @description pipeline_finished=true but no matched path AND no resolvable
             * program — the pipe ran to completion without producing a
             * routable artifact (LLM degraded, program got deleted, etc.).
             * Report `failed` so the CoT page renders the inline summary
             * instead of attempting to redirect.
             */
            200: {
                content: {
                    "application/json": {
                        /** @enum {string} */
                        status: "failed";
                        outcome: null;
                        target: null;
                    } | {
                        /** @enum {string} */
                        status: "completed";
                        /** @enum {string} */
                        outcome: "program";
                        target: {
                            /** @enum {string} */
                            type: "program";
                            guid: string;
                            subproject_id: string;
                            name: string;
                            url: string;
                        };
                    } | {
                        /** @enum {string} */
                        status: "completed";
                        /** @enum {string} */
                        outcome: "path";
                        target: {
                            /** @enum {string} */
                            type: "path";
                            id: number;
                            slug: string;
                            name: string;
                            url: string;
                        };
                    } | {
                        /** @enum {string} */
                        status: "in_progress";
                        outcome: null;
                        target: null;
                    };
                };
            };
            404: {
                content: {
                    "application/json": {
                        /** @enum {string} */
                        error: "deal_not_found";
                    };
                };
            };
        };
    };
    /**
     * #1412 0.2 — anonymous replay feed: GET /api/deal/{guid}/events
     * @description Same `after_seq` sequence cursor as the member endpoint
     * (DealWizardController::events), but with a STRICT non-sensitive
     * projection: deal_events payloads carry intake content —
     * `deal.created` ships the raw problem statement, `deal.info_collected`
     * ships answer_keys, `deal.step.completed` ships full step results —
     * so the public feed whitelists {sequence, event_type, created_at}
     * and adds only the routing-relevant {from, to} pair on
     * `deal.state.*` rows. The payload column is NEVER serialized here
     * (epic risk 7: public vs member payload split). Never reuse the
     * member DealResource (it includes `problem`) on this surface.
     *
     * The guid IS the Deal primary key (PipelineDealActivator vends
     * `deal_guid => $deal->id`). Resolution bypasses the subproject
     * global scope because the visitor is anonymous and carries no
     * X-Domain context — cross-tenant by design, mirroring status().
     */
    "deals.public.events": {
        parameters: {
            query?: {
                after_seq?: string;
            };
            path: {
                guid: string;
            };
        };
        responses: {
            200: {
                content: {
                    "application/json": {
                        events: string;
                        after_seq: number | 0;
                        count: string;
                    };
                };
            };
            404: {
                content: {
                    "application/json": {
                        /** @enum {string} */
                        error: "deal_not_found";
                    };
                };
            };
        };
    };
