    /**
     * Subscriber VERIFICATION handshake. When a subscriber endpoint is
     * saved in the Fitbit dev console, Fitbit sends two unsigned GETs:
     * one with the configured verification code (must answer 204) and one
     * with a deliberately wrong code (must answer 404). Anything without
     * a configured code fails closed on 404
     */
    "fitbit.verifySubscriber": {
        responses: {
            /** @description No content */
            204: {
                content: never;
            };
            404: {
                content: never;
            };
        };
    };
    /**
     * Notification ingress. VerifyFitbitWebhook has already authenticated
     * the HMAC before this method runs. Notifications carry no
     * measurements — each is a thin pointer, so we queue one
     * FetchFitbitMeasurements per (notification, matched tenant) and ACK
     * 204 immediately (Fitbit requires a sub-5-second 204; slow or non-2xx
     * responders get their subscription revoked)
     */
    "fitbit.notifications": {
        responses: {
            /** @description No content */
            204: {
                content: never;
            };
        };
    };
