    /**
     * GET /api/guest/notification/thread/{officialId}
     * @description The guest's message thread with one official, scoped by session_key:
     *   guest → official rows: user_id = officialId, from_user = NULL.
     *
     * v1 is one-directional (resident → official; the official receives the
     * message in their own authed inbox via user_id = officialId). Official →
     * guest replies are out of scope here — they'd need a reply UI on the
     * official's authed surface AND a nullable user_id to address an anonymous
     * recipient; neither exists yet.
     */
    "notification.guestThread": {
        parameters: {
            path: {
                officialId: number;
            };
        };
        responses: {
            /** @description Paginated set of `NotificationResource` */
            200: {
                content: {
                    "application/json": {
                        data: components["schemas"]["NotificationResource"][];
                        links: {
                            first: string | null;
                            last: string | null;
                            prev: string | null;
                            next: string | null;
                        };
                        meta: {
                            current_page: number;
                            from: number | null;
                            last_page: number;
                            /** @description Generated paginator links. */
                            links: ({
                                url: string | null;
                                label: string;
                                active: boolean;
                            })[];
                            /** @description Base path for paginator generated URLs. */
                            path: string | null;
                            /** @description Number of items shown per page. */
                            per_page: number;
                            /** @description Number of the last item in the slice. */
                            to: number | null;
                            /** @description Total number of items being paginated. */
                            total: number;
                        };
                    };
                };
            };
            /** @description An error */
            401: {
                content: {
                    "application/json": {
                        /**
                         * @description Error overview.
                         * @example A valid guest session is required.
                         */
                        message: string;
                    };
                };
            };
            404: components["responses"]["ModelNotFoundException"];
        };
    };
