    /**
     * GET /api/v1/home-feedback — wired in routes/subproject.php
     * @description PUBLIC (no auth — like /api/load). The active tenant is resolved
     * from the X-Domain header by SetDomainContext (in the `api`
     * middleware group). Powers CI-WWW's homepage testimonial carousel
     * (the <feedback-card> row).
     *
     * Returns up to 8 feedback items belonging to the CURRENT tenant's
     * non-Personal programs (ProgramFeedback → Program where
     * programs.subproject_id == the resolved subproject), highest-rated
     * then newest first. Each item is shaped for the CI-WWW FeedbackCard
     * by HomeFeedbackResource:
     *
     *   { id, name, role, quote, avatar, rating }
     *
     * Tenant-safe + indexed: the inner whereHas filters on the indexed
     * programs.subproject_id (see migration
     * 2026_03_23_121330_add_subproject_id_to_key_models_table). No tenant
     * resolves (apex hosts, unknown X-Domain) → { data: [] }, and a tenant
     * with no feedback also returns { data: [] } so the client falls back
     * to its static testimonial pairs without erroring.
     */
    "programFeedback.homeFeedback": {
        responses: {
            /** @description Array of `HomeFeedbackResource` */
            200: {
                content: {
                    "application/json": {
                        data: components["schemas"]["HomeFeedbackResource"][];
                    } | {
                        data: string[];
                    };
                };
            };
        };
    };
    "programSale.handleWebhook": {
        responses: {
            /**
             * @description `JsonResource`
             *
             * Replay — already accepted (and possibly already processed).
             * 200 OK tells Stripe to stop retrying.
             */
            200: {
                content: {
                    "application/json": {
                        data: components["schemas"]["JsonResource"];
                    } | {
                        successfully: boolean;
                        deduped: boolean;
                    };
                };
            };
            /**
             * @description No detail leak — distinguishing malformed payload from bad sig
             * would help an attacker tune their forgery.
             */
            400: {
                content: {
                    "application/json": {
                        /** @enum {string} */
                        error: "Invalid webhook signature";
                    };
                };
            };
            500: {
                content: {
                    "application/json": {
                        /** @enum {string} */
                        error: "Webhook handler failed";
                    };
                };
            };
            503: {
                content: {
                    "application/json": {
                        /** @enum {string} */
                        error: "Webhook handling not configured";
                    };
                };
            };
        };
    };
