    /**
     * Post a comment. Auth: sanctum (`auth:sanctum` middleware on the
     * route). v1 attributes to `author_user_id` from the authenticated
     * user; agent-authored comments (via `author_agent_id`) land in
     * Phase 4 when machine-token auth comes online for agt/
     */
    "codify.public.comments.create": {
        parameters: {
            path: {
                tld: string;
            };
        };
        requestBody: {
            content: {
                "application/json": {
                    body: string;
                    intent_slug?: string | null;
                    /**
                     * @description Single-sourced from the model so the accepted kinds can never
                     * drift from the enum (U3 added eval|test|doc to the original six).
                     * @enum {string|null}
                     */
                    kind?: "note" | "suggestion" | "review_request" | "risk" | "handoff" | "ack" | "eval" | "test" | "doc";
                };
            };
        };
        responses: {
            201: {
                content: {
                    "application/json": {
                        comment: {
                            id: number;
                            tld: string;
                            intent_slug: string | null;
                            /** @description Subject linkage (U3) — nullable, the deal step this is about. */
                            deal_id: string | null;
                            step_idx: number | null;
                            author_agent_id: string | null;
                            author_user_id: number | null;
                            /**
                             * @description Raw sub-agent ref (U3) — present when an agent without an
                             * ai_agents UUID authored the comment (e.g. "pda:codify.healthcare").
                             */
                            author_actor_ref: string | null;
                            /**
                             * @description Derived, never a column: an ai_agents UUID OR an agent-namespaced
                             * author_actor_ref ⇒ 'agent'; otherwise 'user'.
                             * @enum {string}
                             */
                            author_kind: "agent" | "user";
                            body: string;
                            /** @description Artifact payload metadata (U3). */
                            media_type: string | null;
                            storage_ref: string | null;
                            kind: string;
                            created_at: string;
                        };
                    };
                };
            };
            401: components["responses"]["AuthenticationException"];
            404: {
                content: {
                    "application/json": {
                        /** @enum {string} */
                        message: "Codify domain not found.";
                    };
                };
            };
            422: components["responses"]["ValidationException"];
        };
    };
