    /**
     * Flat list of every real-world agency subproject under a country tree —
     * e.g. all rows whose `subprojects.domain` matches the
     * `*.<state>.<country>.project20x.com` (state) or
     * `*.<country>.project20x.com` (federal) pattern. Returns the agency's
     * real name, parsed state code, slug for codify-intent lookup, the
     * live intent_count, and the full domain
     * @description Built to drive the CI-MYC sidebar without paginating through
     * `subprojects/search` 50+ times. Replaces the synthetic
     * `codify_domains` stub list (ak-dmv, fbi, ca-coastal, …) that had no
     * real-world correspondence.
     *
     * Public, ?country=usa today. Additional country tails ride the same
     * pattern (extend the regex + LIKE suffix when adding).
     */
    "subprojects.publicAgencyTree": {
        responses: {
            200: {
                content: {
                    "application/json": {
                        country: string;
                        count: string;
                        agencies: [
                            {
                                id: string;
                                name: string;
                                state: string;
                                /** @enum {string} */
                                level: "federal";
                                slug: string;
                                domain: string;
                                intent_count: number;
                            },
                            {
                                id: null;
                                name: string;
                                state: null;
                                /** @enum {string} */
                                level: "federal";
                                slug: string;
                                domain: string;
                                intent_count: number;
                                /** @enum {string} */
                                source: "gov.agencies.json";
                            }
                        ];
                    } | {
                        country: string;
                        /** @enum {integer} */
                        count: 0;
                        agencies: string[];
                    } | ({
                        /** @enum {string} */
                        country: "international";
                        count: string;
                        agencies: [
                            {
                                id: string;
                                name: string;
                                country: string;
                                country_name: string;
                                state: string | null;
                                /** @enum {string} */
                                level: "state" | "national";
                                slug: string;
                                domain: string;
                                intent_count: number;
                            }
                        ];
                    });
                };
            };
        };
    };
