    /**
     * Webhook ingress. VerifyWithingsWebhook middleware has already
     * authenticated the HMAC before this method runs. We parse the
     * envelope via the WithingsAdapter and dispatch
     * IngestWithingsMeasurement onto the kpi-ingest queue per
     * architecture §1. ACK is returned immediately so Withings does not
     * retry while the job is still working
     */
    "withings.getData": {
        responses: {
            /**
             * @description The response body intentionally surfaces `subproject_id` so
             * integration tests can confirm tenant resolution (device-derived
             * first, X-Domain fallback) before the queue job ran.
             *
             * Withings requires a fast 2xx ACK (non-2xx triggers retries and
             * can revoke the notification subscription), so unmatched
             * deliveries are ACKed but flagged in the body and the log.
             */
            200: {
                content: {
                    "application/json": {
                        /** @enum {string} */
                        status: "accepted";
                        subproject_id: string;
                    } | {
                        /** @enum {string} */
                        status: "unmatched";
                        subproject_id: null;
                    };
                };
            };
        };
    };
